syntax:
Perform arithmetic operations with overflow checks, e.g., using compiler intrinsics or manual comparisons:

if ((b > 0 && a > std::numeric_limits<int>::max() - b) ||
    (b < 0 && a < std::numeric_limits<int>::min() - b)) {
    // handle overflow
}
else {
    a = a + b;
}

code_example:
#include <iostream>
#include <limits>
int main() {
    int a = -32754;
    int b = -15;
    if ((b > 0 && a > std::numeric_limits<int>::max() - b) ||
        (b < 0 && a < std::numeric_limits<int>::min() - b)) {
        std::cerr << "Integer overflow detected!" << std::endl;
    } else {
        int sum = a + b;
        std::cout << "Sum: " << sum << std::endl;
    }
    return 0;
}
